import numpy as np
def detect(g):
    g=np.array(g); H,W=g.shape; out=[]
    for s in (3,5):
        for r in range(H-s+1):
            for c in range(W-s+1):
                sub=g[r:r+s,c:c+s]
                b=sub[0,0]
                if (sub[0]==b).all() and (sub[-1]==b).all() and (sub[:,0]==b).all() and (sub[:,-1]==b).all():
                    inner=sub[1:-1,1:-1]
                    if len(set(inner.flatten()))==1 and inner[0,0]!=b:
                        out.append((r,c,int(b),int(inner[0,0])))
    return out
