from collections import Counter
def find_blocks(I):
    I=np.array(I); res=[]
    for r in range(I.shape[0]-2):
        for c in range(I.shape[1]-2):
            f=int(I[r][c])
            if f==0: continue
            sub=I[r:r+3,c:c+3]
            if not ((sub[0]==f).all() and (sub[-1]==f).all() and (sub[:,0]==f).all() and (sub[:,-1]==f).all()): continue
            res.append((r+1,c+1,int(f),int(sub[1,1])))
    return res
def solve(I, fill_all=True):
    I=np.array(I); db=find_blocks(I)
    ci=[v for _,_,_,v in db]
    mode=Counter(ci).most_common(1)[0][0]
    mk=[(r,c,v) for r,c,f,v in db if v!=mode]
    out=I.copy(); H,W=I.shape
    bgv=max(set(int(x) for x in I.flatten())-{x for _,_,_,x in db}, key=lambda v:int((I==v).sum()))
    # build set of block cells (interior and frame) to exclude
    blkset=set()
    for r,c,f,_ in db:
        for rr in range(r-1,r+3): blkset.add((rr,c))
        for cc in range(c-1,c+3): blkset.add((r,cc))
    for i,(r1,c1,v1) in enumerate(mk):
        for j,(r2,c2,v2) in enumerate(mk):
            if i>=j: continue
            if r1==r2:
                lo,hi=min(c1,c2),max(c1,c2)
                for c in range(lo,hi+1):
                    if fill_all or (r1,c) not in blkset:
